// #13/AK7: pseudo language for UI tests. Every text of the app is marked and lengthened, so a test sees
// at once which text is cut off or overflows. Not a language for users: no ARB file, only the test
// localization in pseudo_localizations.dart (generated by tool/pseudo_l10n.dart).
import 'package:flutter/rendering.dart';
import 'package:material_ui/material_ui.dart';
import 'package:flutter_test/flutter_test.dart';

/// Start and end marks of a pseudo text; a text without the end mark on screen was cut off.
const pseudoStart = '⟦', pseudoEnd = '⟧';

/// Share by which a text grows (translations are often 30–40 % longer than English).
const pseudoGrowth = 0.4;

const _accents = {
  'a': 'á', 'b': 'ƀ', 'c': 'ç', 'd': 'ð', 'e': 'é', 'f': 'ƒ', 'g': 'ĝ', //
  'h': 'ĥ', 'i': 'î', 'j': 'ĵ', 'k': 'ķ', 'l': 'ļ', 'm': 'ɱ', 'n': 'ñ',
  'o': 'ö', 'p': 'þ', 'q': 'ǫ', 'r': 'ŕ', 's': 'š', 't': 'ţ', 'u': 'û',
  'v': 'ṽ', 'w': 'ŵ', 'x': 'ẋ', 'y': 'ý', 'z': 'ž', 'A': 'Å', 'B': 'Ɓ',
  'C': 'Ç', 'D': 'Ð', 'E': 'É', 'F': 'Ƒ', 'G': 'Ĝ', 'H': 'Ĥ', 'I': 'Î',
  'J': 'Ĵ', 'K': 'Ķ', 'L': 'Ļ', 'M': 'Ṁ', 'N': 'Ñ', 'O': 'Ö', 'P': 'Þ',
  'Q': 'Ǫ', 'R': 'Ŕ', 'S': 'Š', 'T': 'Ţ', 'U': 'Û', 'V': 'Ṽ', 'W': 'Ŵ',
  'X': 'Ẋ', 'Y': 'Ý', 'Z': 'Ž',
};

/// [text] with accented letters, lengthened by [pseudoGrowth] and between the marks.
String pseudo(String text) {
  final accented = text.split('').map((c) => _accents[c] ?? c).join();
  final pad = '·' * (text.length * pseudoGrowth).ceil();
  return '$pseudoStart$accented$pad$pseudoEnd';
}

Iterable<RenderParagraph> _paragraphs() sync* {
  for (final e in find.byType(RichText).evaluate()) {
    final r = e.renderObject;
    if (r is RenderParagraph && r.attached && r.hasSize) {
      if (r.text.toPlainText().contains(pseudoStart)) yield r;
    }
  }
}

/// Number of texts of the app on screen (with pseudo marks).
int pseudoTexts(WidgetTester tester) => _paragraphs().length;

/// Texts of the app on screen that are cut off, with the reason: more lines than allowed (also an
/// ellipsis), a line that may not wrap but is wider than its box, or a single word wider than its box.
List<String> cutTexts(WidgetTester tester) {
  final cut = <String>[];
  for (final r in _paragraphs()) {
    final text = r.text.toPlainText();
    final width = r.size.width + 0.5;
    if (r.didExceedMaxLines) {
      cut.add('$text: more lines than allowed');
    } else if (!r.softWrap && r.getMaxIntrinsicWidth(double.infinity) > width) {
      cut.add('$text: wider than its box');
    } else if (r.getMinIntrinsicWidth(double.infinity) > width) {
      cut.add('$text: a word wider than its box');
    }
  }
  return cut;
}
